import limited_client as r,numpy as np
from scipy.spatial.transform import Rotation
G=[.04,.04]
def pose():
 x=r.observe()['robot'];a=x['tcp_quaternion_wxyz'];return np.array(x['joint_positions']),np.array(x['tcp_position']),Rotation.from_quat([a[1],a[2],a[3],a[0]])
def act(q):r.step(np.r_[q,G].tolist())
q0,p0,R0=pose();print('BASE',q0.tolist(),p0.tolist())
for i in range(7):
 t=q0.copy();t[i]+=.045
 for _ in range(2):act(t)
 q,p,R=pose();print('COL',i,'dq',np.round(q-q0,4).tolist(),'dp',np.round(p-p0,4).tolist(),'dr',np.round((R0.inv()*R).as_rotvec(),4).tolist())
 for _ in range(5):act(q0)
print('FINAL',r.observe()['robot']['tcp_position'],r.status())
PY

